  const text = await res.text();
  console.log(`  -> ${res.status}`);
  if (!res.ok) {
    console.log(`  ERROR: ${text}`);
    return null;
  }
  try { return JSON.parse(text); } catch { return text; }
}

async function main() {
  // Step 1: Create a customer
